import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, uniqueName, inviteAndJoin } from './helpers';

test.describe(`group creator: start a new group and invite my friends into it`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  // [Verifier] NOTE: this app's multi-topology rail (UnitRail, testids
  // create-unit-btn/field-unit-name/unit-create-submit/unit-list-item) is
  // only mounted when `!ws.injectedContext` (AppPage.tsx). The e2e isolation
  // harness always logs in via a context-carrying auth hash, so
  // `injectedContext` is permanently true for every page in this harness and
  // the rail never renders. This test exercises the documented contract
  // (per UnitRail.tsx's own comment: "kept mounted so the multi e2e stories
  // can drive unit management") — if the rail's visibility gate is the bug
  // it looks like, this test will fail and correctly surface it.
  test('after the creator names the group and confirms, every invited member sees the group in their group list within 5s', async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);

      // Get both nodes into ONE shared workspace/namespace first (the group
      // rail lives inside a namespace, not standalone).
      await inviteAndJoin(pageA, pageB);

      const groupName = uniqueName('group');
      await pageA.getByTestId('create-unit-btn').click();
      await pageA.getByTestId('field-unit-name').fill(groupName);
      await pageA.getByTestId('unit-create-submit').click();

      await expect(
        pageB.getByTestId('unit-list-item').filter({ hasText: groupName }),
      ).toBeVisible({ timeout: 5_000 });
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });
});
